using System;using System.Globalization;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin.Operations{public partial class Exceptions:AdminPage{protected void Page_Load(object s,EventArgs e){if(!IsPostBack)Bind();}protected void chkOpenOnly_CheckedChanged(object s,EventArgs e){Bind();}private void Bind(){var items=ServiceFactory.CreateOperationsAdminService().GetCannotProceedReports(new ExceptionQuery{OpenOnly=chkOpenOnly.Checked});rptItems.DataSource=items;rptItems.DataBind();pnlResults.Visible=items.Count>0;pnlEmpty.Visible=items.Count==0;}protected string FormatTime(object utc){return ServiceFactory.CreateOperationsAdminService().ToOperationalTime(Convert.ToDateTime(utc)).ToString("dd MMM yyyy HH:mm",CultureInfo.CurrentCulture);}}}
